const input = $input.first().json;

// Handle webhook output wrapped in "body" or sent directly
const payload = input.body ?? input;

const datasets = Array.isArray(payload.datasets)
  ? payload.datasets
  : [];

function isMacMetadata(value) {
  const name = String(value ?? "").replace(/\\/g, "/");
  return (
    name.includes("/__MACOSX/") ||
    name.startsWith("__MACOSX/") ||
    name === "__MACOSX" ||
    name === ".DS_Store" ||
    name.endsWith("/.DS_Store") ||
    name.split("/").some(part => part.startsWith("._"))
  );
}

function cleanName(value) {
  return String(value ?? "").trim();
}

const cleanedDatasets = [];

for (const dataset of datasets) {
  const datasetName = cleanName(dataset.dataset_name);

  if (!datasetName || isMacMetadata(datasetName)) continue;

  const tables = Array.isArray(dataset.tables)
    ? dataset.tables
    : [];

  const cleanedTables = [];

  for (const table of tables) {
    const tableName = cleanName(table.table_name);

    if (!tableName || isMacMetadata(tableName)) continue;

    const rawColumns = Array.isArray(table.columns)
      ? table.columns
      : Array.isArray(table.header_row)
        ? table.header_row
        : [];

    const columns = rawColumns
      .map(column => {
        if (typeof column === "string") return cleanName(column);

        if (column && typeof column === "object") {
          return cleanName(
            column.column_name ?? column.name ?? column._name
          );
        }

        return "";
      })
      .filter(column =>
        column &&
        !isMacMetadata(column) &&
        !/[\x00-\x08\x0B\x0C\x0E-\x1F\x7F]/.test(column)
      );

    // Remove tables with no valid columns
    if (columns.length === 0) continue;

    cleanedTables.push({
      table_name: tableName,
      columns: [...new Set(columns)]
    });
  }

  // Remove datasets with no remaining valid tables
  if (cleanedTables.length === 0) continue;

  cleanedDatasets.push({
    dataset_name: datasetName,
    tables: cleanedTables
  });
}

// Structured input for the LLM node
const schemaInput = {
  datasets: cleanedDatasets,
  total_datasets: cleanedDatasets.length,
  total_tables: cleanedDatasets.reduce(
    (sum, dataset) => sum + dataset.tables.length, 0
  ),
  total_columns: cleanedDatasets.reduce(
    (sum, dataset) =>
      sum + dataset.tables.reduce(
        (tableSum, table) => tableSum + table.columns.length, 0
      ),
    0
  )
};

return [{
  json: {
    schema_input: JSON.stringify(schemaInput, null, 2),
    source_schema: cleanedDatasets,
    total_datasets: schemaInput.total_datasets,
    total_tables: schemaInput.total_tables,
    total_columns: schemaInput.total_columns
  }
}];

const input = $input.first().json;

let schema = input.response ?? input.consolidated_schema ?? input;

if (typeof schema === "string") {
  schema = schema.replace(/```json\s*/i, "").replace(/```\s*/g, "").trim();

  try {
    schema = JSON.parse(schema);
  } catch (e) {
    return [{
      json: {
        validation_status: "failed",
        error: "LLM response is not valid JSON"
      }
    }];
  }
}

const valid =
  schema &&
  Array.isArray(schema.entities) &&
  Array.isArray(schema.source_mappings) &&
  Array.isArray(schema.relationships) &&
  Array.isArray(schema.uncertainties);

if (!valid) {
  return [{
    json: {
      validation_status: "failed",
      error: "Required schema sections are missing or invalid.",
      received_sections: Object.keys(schema || {}),
      consolidated_schema: schema,
      source_schema: input.source_schema,
      schema_input: input.schema_input
    }
  }];
}

return [{
  json: {
    validation_status: "valid_json",
    consolidated_schema: schema,
    source_schema: input.source_schema,
    schema_input: input.schema_input,
    total_datasets: input.total_datasets,
    total_tables: input.total_tables,
    total_columns: input.total_columns
  }
}];

const items = $input.all().map(item => item.json);

// Find the two inputs, even if Merge outputs separate items
const consolidatedItem = items.find(
  item => item.consolidated_schema
);

const sourceItem = items.find(
  item => Array.isArray(item.source_schema)
);

if (!consolidatedItem || !sourceItem) {
  return [{
    json: {
      status: "error",
      message: "Missing consolidated_schema or source_schema",
      received_items: items.length
    }
  }];
}

const schema = consolidatedItem.consolidated_schema;
const sourceSchema = sourceItem.source_schema;

// Build the complete list of original column paths
const originalColumns = [];

for (const dataset of sourceSchema) {
  for (const table of dataset.tables || []) {
    for (const column of table.columns || []) {
      originalColumns.push(
        `${dataset.dataset_name}.${table.table_name}.${column}`
      );
    }
  }
}

// Collect source references from the consolidated output
const references = new Set();

function scan(value) {
  if (typeof value === "string") {
    references.add(value);
    return;
  }

  if (Array.isArray(value)) {
    value.forEach(scan);
    return;
  }

  if (value && typeof value === "object") {
    if (value.dataset && value.table && value.column) {
      references.add(
        `${value.dataset}.${value.table}.${value.column}`
      );
    }

    Object.values(value).forEach(scan);
  }
}

scan(schema);

const representedColumns = originalColumns.filter(
  column => references.has(column)
);

const missingColumns = originalColumns.filter(
  column => !references.has(column)
);

const completenessPercent = originalColumns.length
  ? Math.round(
      representedColumns.length / originalColumns.length * 100
    )
  : 100;

return [{
  json: {
    status: missingColumns.length === 0
      ? "complete"
      : "incomplete",
    validation_status: consolidatedItem.validation_status,
    total_source_columns: originalColumns.length,
    represented_columns: representedColumns.length,
    missing_column_count: missingColumns.length,
    completeness_percent: completenessPercent,
    missing_columns: missingColumns,
    consolidated_schema: schema
  }
}];

const input = $input.first()?.json ?? {};

// Handle the wrapper shown in your actual node output.
const result = input.items?.[0]?.json ?? input;

const entities = result.consolidated_schema?.entities ?? [];
const sourceColumns = [];

// Extract every source column from every entity.
for (const entity of entities) {
  for (const source of entity.source_columns ?? []) {
    if (typeof source !== "string") continue;

    const parts = source.split(".");
    const columnName = parts.pop();
    const tableName = parts.pop();
    const datasetName = parts.join(".");

    sourceColumns.push({
      dataset_name: datasetName,
      table_name: tableName,
      column_name: columnName,
      source_column: source,
      consolidated_entity: entity.entity_name
    });
  }
}

// Remove duplicate source-column references.
const uniqueColumns = [
  ...new Map(
    sourceColumns.map(col => [col.source_column, col])
  ).values()
];

return [{
  json: {
    ...result,
    source_columns: uniqueColumns,
    extracted_source_column_count: uniqueColumns.length,
    extraction_status:
      uniqueColumns.length > 0 ? "success" : "no_columns_found"
  }
}];

// Get all incoming items
const allItems = $input.all();

// Get the schema data
const data = allItems[0].json;
const schema = data.consolidated_schema;

// Prepare the LLM payload
const llm_payload = {
  entities: schema.entities || [],
  source_mappings: schema.source_mappings || [],
  relationships: schema.relationships || [],
  uncertainties: schema.uncertainties || [],
  source_column_count: data.total_source_columns || 0,
  completeness_percent: data.completeness_percent || 0
};

return [
  {
    json: {
      llm_payload
    }
  }
];

const item = $input.first().json;

// Get the LLM response
const response = item.response || item.items?.[0]?.json?.response;

// Convert response string to JSON
const data = typeof response === "string"
  ? JSON.parse(response)
  : response;

// Return formatted output
return [
  {
    json: {
      consolidated_schema: data?.consolidated_schema || {},
      validation_summary: data?.validation_summary || {},
      model: item.model || item.items?.[0]?.json?.model || null,
      tokensUsed: item.tokensUsed || item.items?.[0]?.json?.tokensUsed || 0
    }
  }
];
